begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(13);
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000001'), ('10000000-0000-4000-8000-000000000002');
insert into public.nuclei(id,type,name,purpose,created_by) values ('20000000-0000-4000-8000-000000000001','amigos','Teste','Cuidar','10000000-0000-4000-8000-000000000001');
insert into public.nucleus_members(nucleus_id,user_id,role) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','admin');
insert into public.nucleus_invitations(id,nucleus_id,code,created_by) values ('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',repeat('a',32),'10000000-0000-4000-8000-000000000001');
insert into public.nuclei(id,type,name,purpose,created_by) values ('20000000-0000-4000-8000-000000000002','amigos','Outro','Outro contexto','10000000-0000-4000-8000-000000000001');
insert into public.nucleus_invitations(id,nucleus_id,code,created_by) values ('30000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',repeat('c',32),'10000000-0000-4000-8000-000000000001');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.accept_invitation(repeat('a',32))$$, 'aceite cria vínculo');
select lives_ok($$select public.accept_invitation(repeat('a',32))$$, 'aceite repetido seguro');
select throws_ok($$select public.revoke_nucleus_invitation('20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001')$$,'42501','not authorized','participante não revoga');
select is((select count(*)::int from public.nucleus_invitations),0,'participante não lê convites');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.revoke_nucleus_invitation('20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001')$$,'administrador revoga');
reset role;
-- now() é constante nesta transação: usar data anterior prova que não há sobrescrita.
update public.nucleus_invitations set revoked_at='2000-01-01T00:00:00Z' where id='30000000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.revoke_nucleus_invitation('20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001')$$,'revogação repetida segura');
select is((select revoked_at from public.nucleus_invitations where id='30000000-0000-4000-8000-000000000001'),'2000-01-01T00:00:00Z'::timestamptz,'repetir preserva data');
select throws_ok($$select public.revoke_nucleus_invitation('20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002')$$,'P0002','invitation unavailable','ID fora do contexto não altera');
select throws_ok($$select public.accept_invitation(null)$$,'22023','authentication required or invalid code','código nulo negado');
select throws_ok($$select public.accept_invitation(repeat('a',32))$$,'P0002','invitation unavailable','revogado não permite aceitar');
reset role;
insert into public.nucleus_invitations(nucleus_id,code,created_by,expires_at) values ('20000000-0000-4000-8000-000000000001',repeat('b',32),'10000000-0000-4000-8000-000000000001',now()-interval '1 minute');
set local role authenticated;
select throws_ok($$select public.accept_invitation(repeat('b',32))$$,'P0002','invitation unavailable','expirado negado');
reset role;
select is((select count(*)::int from public.nucleus_members where nucleus_id='20000000-0000-4000-8000-000000000001'),2,'revogar preserva membros');
select ok(not has_function_privilege('anon','public.revoke_nucleus_invitation(uuid,uuid)','execute'),'anônimo não executa');
select * from finish();
rollback;
